import pytest
from hypothesis import given
import hypothesis.strategies as st
from solution import valid_date


# Obviously-correct reference model derived strictly from SPEC rules.
def _ref(date):
    # Rule 1: not empty
    if date == "":
        return False
    # Rule 4: format mm-dd-yyyy => exactly 10 chars, dashes at 2 and 5,
    # digits elsewhere (2-digit mm, 2-digit dd, 4-digit yyyy)
    if len(date) != 10:
        return False
    if date[2] != "-" or date[5] != "-":
        return False
    m_s, d_s, y_s = date[:2], date[3:5], date[6:]
    if not (m_s.isdigit() and d_s.isdigit() and y_s.isdigit()):
        return False
    m = int(m_s)
    d = int(d_s)
    # Rule 3: months 1..12
    if not (1 <= m <= 12):
        return False
    # Rule 2: days per month
    if m in (1, 3, 5, 7, 8, 10, 12):
        max_d = 31
    elif m in (4, 6, 9, 11):
        max_d = 30
    else:  # m == 2
        max_d = 29
    if not (1 <= d <= max_d):
        return False
    return True


# ---- explicit spec examples ----
def test_spec_example_03_11_2000_true():
    assert valid_date('03-11-2000') is True


def test_spec_example_15_01_2012_false():
    assert valid_date('15-01-2012') is False


def test_spec_example_04_0_2040_false():
    assert valid_date('04-0-2040') is False


def test_spec_example_06_04_2020_true():
    assert valid_date('06-04-2020') is True


def test_spec_example_slash_separator_false():
    assert valid_date('06/04/2020') is False


def test_empty_string_is_invalid():
    assert valid_date('') is False


def test_month_12_is_valid_december():
    # Boundary named in spec: months up to 12 inclusive.
    assert valid_date('12-15-2000') is True
    assert valid_date('12-31-1999') is True
    assert valid_date('12-01-2020') is True


def test_month_upper_boundary_12_vs_13():
    assert valid_date('12-10-2000') is True
    assert valid_date('13-10-2000') is False


def test_month_lower_boundary_00_vs_01():
    assert valid_date('00-10-2000') is False
    assert valid_date('01-10-2000') is True


def test_day_lower_boundary_zero_invalid_all_months():
    for m in ["01", "02", "03", "04", "05", "06", "07", "08", "09", "10", "11", "12"]:
        assert valid_date(f'{m}-00-2000') is False


def test_february_boundaries():
    assert valid_date('02-01-2000') is True
    assert valid_date('02-29-2000') is True
    assert valid_date('02-30-2000') is False
    assert valid_date('02-31-2000') is False
    assert valid_date('02-00-2000') is False


def test_30_day_months_reject_31():
    for m in ["04", "06", "09", "11"]:
        assert valid_date(f'{m}-30-2000') is True
        assert valid_date(f'{m}-31-2000') is False


def test_31_day_months_accept_31():
    for m in ["01", "03", "05", "07", "08", "10", "12"]:
        assert valid_date(f'{m}-31-2000') is True
        assert valid_date(f'{m}-32-2000') is False


def test_format_requires_dashes_at_positions_2_and_5():
    assert valid_date('06/04/2020') is False
    assert valid_date('06.04.2020') is False
    assert valid_date('06:04:2020') is False
    assert valid_date('06 04 2020') is False
    assert valid_date('06-04/2020') is False
    assert valid_date('06/04-2020') is False


def test_format_requires_length_10():
    assert valid_date('6-04-2020') is False
    assert valid_date('06-4-2020') is False
    assert valid_date('06-04-20') is False
    assert valid_date('06-04-20200') is False
    assert valid_date('006-04-2020') is False


def test_non_digit_components_rejected():
    assert valid_date('ab-cd-efgh') is False
    assert valid_date('0a-11-2000') is False
    assert valid_date('03-1b-2000') is False
    assert valid_date('03-11-20a0') is False


# ---- property-based tests ----

@given(m=st.integers(min_value=1, max_value=12))
def test_property_all_months_can_be_valid(m):
    max_d = {1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30,
             7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}[m]
    date = f"{m:02d}-01-2000"
    assert valid_date(date) is True
    date2 = f"{m:02d}-{max_d:02d}-2000"
    assert valid_date(date2) is True


@given(m=st.sampled_from([1, 3, 5, 7, 8, 10, 12]),
       d=st.integers(min_value=1, max_value=31))
def test_property_31_day_months_valid_range(m, d):
    date = f"{m:02d}-{d:02d}-2000"
    assert valid_date(date) is True


@given(m=st.sampled_from([4, 6, 9, 11]),
       d=st.integers(min_value=1, max_value=30))
def test_property_30_day_months_valid_range(m, d):
    date = f"{m:02d}-{d:02d}-2000"
    assert valid_date(date) is True


@given(d=st.integers(min_value=1, max_value=29))
def test_property_february_valid_range(d):
    date = f"02-{d:02d}-2000"
    assert valid_date(date) is True


@given(m=st.integers(min_value=1, max_value=12),
       d=st.integers(min_value=0, max_value=32),
       y=st.integers(min_value=0, max_value=9999))
def test_property_agrees_with_reference_model(m, d, y):
    date = f"{m:02d}-{d:02d}-{y:04d}"
    assert valid_date(date) == _ref(date)


@given(s=st.text(alphabet=st.characters(min_codepoint=45, max_codepoint=57), min_size=0, max_size=12))
def test_property_agrees_with_reference_on_arbitrary_short_strings(s):
    assert valid_date(s) == _ref(s)


@given(m=st.integers(min_value=1, max_value=12),
       y=st.integers(min_value=0, max_value=9999),
       bad_day=st.integers(min_value=32, max_value=99))
def test_property_day_above_31_always_invalid(m, y, bad_day):
    date = f"{m:02d}-{bad_day:02d}-{y:04d}"
    # day string may be >2 chars; reference says False; check spec rule 2
    assert valid_date(date) is False


@given(y=st.integers(min_value=0, max_value=9999),
       bad_month=st.integers(min_value=13, max_value=99))
def test_property_month_above_12_always_invalid(y, bad_month):
    date = f"{bad_month:02d}-10-{y:04d}"
    assert valid_date(date) is False
